new.content:
pub struct Cache {
    map: HashMap<Key, Thumbnail>,
    recent: VecDeque<Key>,
}

impl Cache {
    fn touch(&mut self, key: &Key) {
        self.recent.retain(|other| other != key);
        self.recent.push_back(key.clone());
    }
}

